620	        { class: 'color-mode-1', name: 'Pink' },
621	        { class: 'color-mode-2', name: 'Teal' },
622	        { class: 'color-mode-3', name: 'Mint' },
623	        { class: 'color-mode-4', name: 'Purple' },
624	        { class: 'color-mode-5', name: 'Orange' }
625	      ];
626	
627	      const getRandomColorMode = () => Math.floor(Math.random() * COLORS.length);
628	      const isTouch = (() => {
629	        if (!window.matchMedia) return false;
630	        const hasCoarsePointer = window.matchMedia('(pointer:coarse)').matches;
631	        const hasTouchEvents = 'ontouchstart' in window;
632	        const hasMaxTouchPoints = (navigator.maxTouchPoints ?? 0) > 0;
633	        return hasCoarsePointer || hasTouchEvents || hasMaxTouchPoints;
634	      })();
