636	      const CONFIG = {
637	        storageKey: 'circle-state',
638	        tapDelay: 300,
639	        colorShiftDuration: 500,
640	        saveDebounceDuration: 100,
641	        keyDebounce: 50,
642	        isTouch
643	      };
