658	      let tapCount = 0;
659	      let tapTimeout = null;
660	      let animatingColorShift = false;
661	      let saveTimeout = null;
662	      let lastKeyTime = 0;
663	
664	      const haptic = (duration) => navigator.vibrate?.(duration);
665	
666	      const getColorClass = (mode) => COLORS[mode % COLORS.length]?.class || '';
667	      const getColorName = (mode) => COLORS[mode % COLORS.length]?.name || '';
668	
669	      const storage = {
670	        save() {
671	          clearTimeout(saveTimeout);
672	          saveTimeout = setTimeout(() => {
673	            try {
674	              localStorage.setItem(CONFIG.storageKey, JSON.stringify(state));
675	            } catch (e) {
676	              // Silently fail on storage errors
677	            }
678	          }, CONFIG.saveDebounceDuration);
679	        },
680	        load() {
681	          try {
682	            const saved = localStorage.getItem(CONFIG.storageKey);
683	            if (saved) {
