711	          }
712	        }
713	      };
714	
715	      const updateUI = () => {
716	        const isActive = state.active;
717	        const hint = isTouch
718	          ? (isActive ? 'Tap twice to cycle • Tap to deactivate' : 'Tap to activate • Tap twice to cycle')
