758	        applyState();
759	        storage.save();
760	      };
761	
762	      const changeColor = (newMode, hapticPattern = 20) => {
763	        if (animatingColorShift || !el.circle) return;
764	        animatingColorShift = true;
765	        state.colorMode = newMode;
766	        state.active = true;
767	        haptic(hapticPattern);
