829	        if (!el.helpModal?.classList.contains('active')) return;
830	
831	        if (e.key === 'Escape') {
832	          e.preventDefault();
833	          modal.close();
834	          return;
835	        }
836	
837	        if (e.key === 'Tab') {
838	          const focusableElements = Array.from(el.helpModal.querySelectorAll('button, [tabindex]'));
