const keyHandlers = {
  ' ': toggleActive,
  'enter': toggleActive,
  'escape': resetState,
  'c': cycleColor,
  'x': randomizeColor,
  'r': resetState,
  '?': modal.open,
  'arrowright': cycleColor,
  'arrowleft': () => {
    if (animatingColorShift || !el.circle) return;
    const newMode = (state.colorMode - 1 + COLORS.length) % COLORS.length;
    changeColor(newMode);
  }
};

const handleKeyDown = (e) => {
  const key = e.key.toLowerCase();
  const handler = keyHandlers[key];
  if (!handler) return;

  const now = Date.now();
  if (now - lastKeyTime < CONFIG.keyDebounce) return;

  e.preventDefault();
  handler();
  lastKeyTime = now;
};

